using System.Collections.ObjectModel;
using CommunityToolkit.Mvvm.ComponentModel;

namespace DocTwin.ViewModels;

public sealed record HelpTopic(string Title, string Body)
{
    public override string ToString() => Title;
}

public partial class HelpViewModel : ObservableObject
{
    private static readonly IReadOnlyList<HelpTopic> AllTopics =
    [
        new("Start here: read-only discovery", "DocTwin helps people find and assess redundant Confluence guidance. It only reads Confluence; it never creates, edits, archives, redirects or deletes pages.\n\n1. Connect with an organisation-approved read token.\n2. Choose a source root and approved external spaces.\n3. Run Quick or Deep discovery.\n4. Select a finding and review captured evidence.\n5. Optionally request AI with explicit sharing consent.\n6. Record a local human decision and export a report.\n\nA finding is not proof of redundancy. Source-of-truth and retirement decisions belong to owners."),
        new("Connection, token and permissions", "Use your HTTPS *.atlassian.net site, Atlassian email and approved API token. Scoped tokens need the site's Cloud ID, not a page ID. Enter connection fields before the token: changing them clears the session token.\n\nRequired scopes: read:user:confluence and read:page:confluence for the connection test; read:hierarchical-content:confluence for descendants; read:content-details:confluence for title search; read:space:confluence for selected-space lookup. No write scope is needed.\n\nWindows Credential Manager storage is optional and requires separate consent after a successful test. Removing a saved connection does not revoke the Atlassian token. IDE/Rovo sign-in is separate."),
        new("Quick versus Deep scans", "Quick is the default: traverse the source hierarchy, search source titles and identifiers, then prioritise up to 100 external body attempts and 2,000 external metadata entries (or your lower body limit). Up to 80 title queries are attempted.\n\nDeep searches titles first (up to 200 queries), then reads remaining inventory within your body budget, up to 5,000 external attempts. Each title query has a 100-result bound; targeted retrieval has a 2,000-candidate bound.\n\nChanging mode starts a fresh scan, not a resume. Time varies with scope, network latency, page sizes and throttling. Neither mode guarantees complete discovery. Cancel is available; retained findings are explicitly partial."),
        new("Title matches and functional overlap", "Source titles drive CQL searches across your approved spaces. Integration identifiers and distinctive terms improve retrieval of rewritten references.\n\nExact/lexical findings use extracted text and five-word shingles. Potential functional overlap additionally requires corroborating specific title terms and shared content words. A shared ID or title alone is insufficient. A combined maintained page may match multiple older references.\n\nA low lexical score can accompany relevant rewritten material. Review the match basis, both original pages, audience, purpose, ownership and current process. The source root is context, not proof of authority."),
        new("Coverage, skipped pages and limits", "Read coverage before interpreting results. Source hierarchy, extractable source content and external inventory completion are separate. Restricted/invisible pages cannot be counted; search indexing is not a site snapshot.\n\nLimits per page: 10 MB API response, 200,000 extracted characters, 10,000 text blocks, 8,000 characters in one block. Oversized pages are skipped with numeric diagnostics, never truncated into a successful comparison. Descendants are still traversed.\n\nImages, attachments, dynamic/include macros and comments are not compared. Empty pages, size limits, HTTP 403, HTTP 404 and other read errors are reported separately. An empty result does not prove there is no duplication."),
        new("Review a pair and record a decision", "Select a discovery row and choose Review selected finding. The first finding is selected automatically. This shows texts and versions captured during scanning. Fetch & compare live pages refreshes two URLs from the configured site.\n\nThe local review panel records an owner-led decision and notes. Both page versions must be positive and known; refresh pages if version information is missing. A decision is attached to the site, page IDs and versions, so a later revision does not inherit approval silently.\n\nFor legacy Bedrock/PB versus maintained MSS guidance, record confirmed ownership and retirement rationale. Do not assume a preferred space or an AI recommendation establishes authority. No decision changes Confluence."),
        new("AI optional: enable the analysis button", "AI is not needed for discovery or local comparison.\n\n1. Select a finding and choose Prepare AI, or on the AI tab choose Load selected discovery finding. Alternatively fetch two live page URLs first.\n2. Confirm that Loaded pair shows the intended pages.\n3. Choose provider, model and approved destination.\n4. Review the settings, then tick the visible sharing-consent checkbox above the Analyse button.\n5. Choose Analyse selected pair with AI.\n\nThe button is disabled if a request is running, no pair is loaded, or consent is missing. Loading another pair or changing provider/model/endpoint/key-variable revokes consent. Opening a tab or importing a profile never sends content. Both captured texts and hierarchy metadata are sent only after approval."),
        new("AI providers, keys and rejected responses", "GitHubCopilot uses Copilot SDK/CLI user sign-in: run copilot login in a terminal. IDE and Microsoft 365 Copilot sign-ins are not assumed. Check subscription and model access.\n\nOpenAICompatible and Claude use API keys from the named environment variable (process first, then Windows user scope). Enter the variable NAME, never the secret, in the app. A chat subscription is not API access. Import copies supported non-secret profile fields only. Review endpoint and model before consent.\n\nHTTP 401: credentials. 403: permissions/policy/model access. 404: endpoint/model. 429: quota/rate/billing. 400/413: request/model/input-size support. AI requests are not automatically retried because they may incur charges.\n\nInput is bounded to 160,000 combined page-text/hierarchy characters and is never silently truncated. Responses must match the schema and contain exact quotes from the pages. A rejected quote, refusal or incomplete response produces no accepted findings. Retry only after reviewing the error and possible charges. Never weaken evidence validation to accept a plausible answer."),
        new("Timeouts, circuit breaker and support logs", "Confluence GET reads allow at most three attempts for HTTP 429/502/503/504 and transport failures. Cancellation is honoured during backoff. A Retry-After over 30 seconds stops the operation instead of retrying early. No retry is performed for authentication, permission or missing-page errors.\n\nA Polly circuit breaker pauses new reads for 30 seconds when at least four logical reads in a 30-second window have a transient failure rate of at least 75%. Outbound concurrency is limited to two sends through response headers per client. No fallback fabricates successful data.\n\nHTTP timeout: 45 seconds. Ordinary operation deadline: three minutes; discovery: 60 minutes. AI HTTP timeout: two minutes.\n\nContent-free structured logs are in %LOCALAPPDATA%\\DocTwin\\logs, with up to seven 5 MB rolling files. Share the support reference and logs through approved channels. Tokens, page text, titles, URLs, email and exception messages are not logged. Unexpected UI errors stop the app rather than continue in an unknown state."),
        new("Local files, exports and recovery", "Local non-secret AI profiles, appearance and versioned human reviews are stored under %LOCALAPPDATA%\\DocTwin. Saves use bounded JSON, an exclusive write lease and atomic replacement. Another instance writing at the same time causes an explicit save failure; retry after it finishes. Invalid history is not overwritten.\n\nBack up local review files before repair. If a file is malformed, preserve it for approved support and restore a known-good backup; do not delete review history as a troubleshooting shortcut. AI keys are not stored in these files.\n\nHTML and CSV exports contain internal titles, links, metrics and review notes. Protect them as company information. Export is local and never publishes to Confluence. Removing a saved token requires Windows Credential Manager removal in the app and separate Atlassian revocation if needed."),
        new("Keyboard, appearance and accessibility", "Use Tab/Shift+Tab to move between controls, arrow keys in lists, Space to toggle consent, and Enter/Space to activate a focused button. Alt+S focuses Help search; Escape closes Help. Search checks both topic titles and text.\n\nSwitch theme changes Light/Dark appearance and saves the preference locally. Configuration areas scroll while evidence/results retain a usable viewport. Use Windows scaling as needed. Native title bars and message boxes follow Windows settings.\n\nKeyboard and minimum-size layout checks are verified, but a full assistive-technology/WCAG AA certification has not been completed.")
    ];

    [ObservableProperty] private string _searchText = string.Empty;
    [ObservableProperty] private HelpTopic? _selectedTopic;
    public ObservableCollection<HelpTopic> Topics { get; } = [];
    public string SearchSummary => Topics.Count == 0 ? "No topics match. Try AI, token, coverage, or timeout." : $"{Topics.Count} help topics";

    public HelpViewModel() => Filter();
    partial void OnSearchTextChanged(string value) => Filter();

    private void Filter()
    {
        var selected = SelectedTopic;
        var terms = SearchText.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        Topics.Clear();
        foreach (var topic in AllTopics.Where(topic => terms.All(term =>
            topic.Title.Contains(term, StringComparison.OrdinalIgnoreCase) || topic.Body.Contains(term, StringComparison.OrdinalIgnoreCase))))
            Topics.Add(topic);
        SelectedTopic = selected != null && Topics.Contains(selected) ? selected : Topics.FirstOrDefault();
        OnPropertyChanged(nameof(SearchSummary));
    }
}
